from pathlib import Path
p=Path('student.html')
s=p.read_text(encoding='utf-8')
old='<div class="honorFoot">ملاحظة العدالة: البيانات غير المسجلة لا تُفترض صفرًا، والطالب الذي تنقصه بيانات أساسية لا يدخل الترتيب العام حتى اكتمالها. أما الغياب عن اختبار مُسجل فيُعامل في ترتيب الشرف كفرصة اختبار لم تُنجز. مكوّن تدريبات المنصة يجمع بين إكمال التدريبات النشطة وجودة أفضل نتيجة معتمدة لكل تدريب.</div>'
new='<div class="honorFoot"><b>قواعد العدالة:</b> كل الحسابات تأتي من محرك دورة التقييم المركزي. غياب أي كويز أو امتحان مسجل = صفر ويدخل بكامل نهاية الاختبار في الحصيلة. تدريبات المنصة المحتسبة هي تدريبات الإعداد المسلّمة قبل الـCutoff فقط، والنشاط بعده لا يغيّر الجولة السابقة. الطالب الذي لديه أعمال قبل الشامل ما زالت قيد المراجعة لا يأخذ مركزًا مؤقتًا، لكنه يرى حالته الشخصية «قيد المراجعة» حتى اكتمال التصحيح.</div>'
if old not in s: raise SystemExit('student honor footnote pattern missing')
p.write_text(s.replace(old,new,1),encoding='utf-8')
print('student honor footnote updated')
